import{_ as a,o as n,a as t,b as p}from"./app.C41L12d5.js";const d="/ascendc.github.io/assets/thread_id_1.BTv0yB9G.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"语言扩展层","link":"/guide/programming_guide/language_extension/language_extension"},{"text":"SIMT BuiltIn关键字","link":"/guide/programming_guide/language_extension/simt_builtin_keywords"}]},"headers":[],"relativePath":"guide/programming_guide/language_extension/simt_builtin_keywords.md","filePath":"guide/programming_guide/language_extension/simt_builtin_keywords.md","outlineHeaders":[{"level":2,"title":"预定义宏","slug":"预定义宏","link":"#预定义宏"},{"level":2,"title":"函数执行空间限定符","slug":"函数执行空间限定符","link":"#函数执行空间限定符"},{"level":2,"title":"地址空间限定符","slug":"地址空间限定符","link":"#地址空间限定符"},{"level":2,"title":"内置常量","slug":"内置常量","link":"#内置常量"},{"level":2,"title":"内置结构体","slug":"内置结构体","link":"#内置结构体"},{"level":2,"title":"内置变量","slug":"内置变量","link":"#内置变量"},{"level":2,"title":"编译器内置数据类型","slug":"编译器内置数据类型","link":"#编译器内置数据类型"},{"level":2,"title":"运算符","slug":"运算符","link":"#运算符"},{"level":2,"title":"核函数（Kernel）配置","slug":"核函数（Kernel）配置","link":"#核函数（Kernel）配置"}],"lastUpdated":1788515292000}'),l={name:"guide/programming_guide/language_extension/simt_builtin_keywords.md"};function c(i,s,e,r,o,h){return n(),t("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>SIMT BuiltIn关键字<span id="ZH-CN_TOPIC_0000002477663934"></span></h1><h2 id="预定义宏">预定义宏<a class="header-anchor" href="#预定义宏">​</a></h2><p>SIMT会提供内置的宏方便用户编写程序。预定义宏一节着重介绍用户在做异构编程时会经常用到的宏，以及宏的解释。</p><ul><li><p><a id="npu-arch"></a><strong>__NPU_ARCH__</strong></p><p>__NPU_ARCH__是Device侧AI Core代码中的预处理宏，用于标识AI处理器的架构版本。通过该宏，开发者可以针对不同AI处理器，差异化进行代码适配和优化。产品型号和NPU架构版本的对应关系如下：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：3510</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持SIMT</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持SIMT</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持SIMT</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品：不支持SIMT</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持SIMT</li></ul></div></li></ul><h2 id="函数执行空间限定符">函数执行空间限定符<span id="section204112391232"></span><a class="header-anchor" href="#函数执行空间限定符">​</a></h2><p>函数执行空间限定符（Function Execution Space Qualifier）指示函数是在Host侧执行还是在Device侧执行，以及能被调用的空间范围。</p><p><strong>表1</strong> 函数执行空间限定符概览</p><p><span id="table121121062614"></span></p><table><thead><tr><th>函数执行空间限定符</th><th>执行空间（Host）</th><th>执行空间（Device）</th><th>允许调用函数空间（Host）</th><th>允许调用函数空间（Device）</th></tr></thead><tbody><tr><td>__host__，无限定符</td><td>√</td><td>x</td><td>√</td><td>x</td></tr><tr><td>__aicore__</td><td>x</td><td>√</td><td>x</td><td>√</td></tr><tr><td>__global__</td><td>x</td><td>√</td><td>√</td><td>x</td></tr></tbody></table><p>__global__修饰的函数是核函数（Kernel）入口，有以下使用约束：</p><ul><li>函数返回类型必须为void，不能是class、struct或者union的成员函数。</li><li>不支持递归调用。</li><li>对__global__函数的调用是异步的，调用后即返回Host侧的主机线程。</li><li>只能被Host侧函数调用，在Device上执行。</li></ul><p>__aicore__修饰的函数只能在Device侧执行，只能被__global__函数，或者其他__aicore__函数调用。</p><p>__host__修饰的函数只能在Host侧被调用和执行。</p><h2 id="地址空间限定符">地址空间限定符<span id="section20787845172517"></span><a class="header-anchor" href="#地址空间限定符">​</a></h2><p>使用地址空间限定符__ubuf__来表示分配在Unified Buffer（UB）上的动、静态内存，静态内存的大小在编译期是确定的，动态内存的大小在核函数（Kernel）执行时确定。</p><ul><li><p>静态内存通过数组分配：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">staticBuf</span><span class="p">[</span><span class="mi">1024</span><span class="p">];</span>
</code></pre></div></li><li><p>动态内存通过以下方式申请使用：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dynamicBuf</span><span class="p">[];</span>
</code></pre></div><p>动态内存的实际内存大小需要在核函数（Kernel）启动时配置，具体内容请参考<a href="#section97005415463">核函数（Kernel）配置</a>。</p></li></ul><h2 id="内置常量">内置常量<span id="section784531219338"></span><a class="header-anchor" href="#内置常量">​</a></h2><p><span id="table878553753515"></span></p><table><thead><tr><th>常量名</th><th>取值</th><th>功能</th></tr></thead><tbody><tr><td>constexpr uint64_t ASC_UB_SIZE</td><td>取值由当前AI处理器决定，若该AI处理器不存在这块空间，则默认配置为0。</td><td>表示当前AI处理器架构下UB的容量，可用于编译期获取UB资源大小。</td></tr></tbody></table><h2 id="内置结构体">内置结构体<span id="section13165113520576"></span><a class="header-anchor" href="#内置结构体">​</a></h2><ul><li><p>dim3<span id="li1136665405"></span></p><p>dim3是内置结构体类型，由3个无符号整数组成，结构体定义为</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">dim3</span><span class="p">{</span>
<span class="w">    </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">;</span>
<span class="w">    </span><span class="n">dim3</span><span class="p">(</span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="kt">unsigned</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">z</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span>
<span class="w">        </span><span class="o">:</span><span class="n">x</span><span class="p">(</span><span class="n">x</span><span class="p">),</span><span class="w"> </span><span class="n">y</span><span class="p">(</span><span class="n">y</span><span class="p">),</span><span class="w"> </span><span class="n">z</span><span class="p">(</span><span class="n">z</span><span class="p">)</span><span class="w"> </span><span class="p">{}</span>
<span class="p">};</span>
</code></pre></div><p>用于指定3个不同维度的大小，三维总数为x * y * z。开发者可以通过如下方式创建dim3结构。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">dim3</span><span class="p">(</span><span class="n">x</span><span class="p">);</span><span class="w"> </span><span class="c1">// 创建一维结构，dimy和dimz为默认值1</span>
<span class="n">dim3</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">);</span><span class="w"> </span><span class="c1">// 创建二维结构，dimz为默认值1</span>
<span class="n">dim3</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">);</span><span class="w"> </span><span class="c1">// 创建三维结构</span>
</code></pre></div></li></ul><h2 id="内置变量">内置变量<span id="section13165113520577"></span><a class="header-anchor" href="#内置变量">​</a></h2><p>当前提供了以下仅在Device上可用的dim3结构的内置变量：</p><ul><li><p>gridDim<span id="li20760123812911"></span></p><p>内置全局变量，只能在核函数（Kernel）中使用，表示整个计算任务在各个维度上分别由多少个线程块构成。</p></li><li><p>blockDim<span id="li076017381191"></span></p><p>内置全局变量，在核函数（Kernel）中可以直接使用，用于获取线程块中配置的线程的三维层次结构，即启动核函数（Kernel）时配置的dim3结构体实例值。blockDim.x，blockDim.y，blockDim.z分别表示线程块中三个维度的线程数。</p></li><li><p>blockIdx<span id="li1676053814914"></span></p><p>内置全局变量，只能在核函数（Kernel）中使用，用于获取块索引。表示当前线程所在的线程块在整个网格中的位置坐标。</p><ul><li>blockIdx.x的范围是[0, gridDim.x - 1]。</li><li>blockIdx.y的范围是[0, gridDim.y - 1]。</li><li>blockIdx.z的范围是[0, gridDim.z - 1]。</li></ul></li><li><p>threadIdx<span id="li7760123814919"></span></p><p>内置全局变量，在核函数（Kernel）中可以直接使用，用于获取当前线程在线程块内部的索引。threadIdx.x，threadIdx.y，threadIdx.z分别表示当前线程在3个维度的索引，threadIdx.x的范围为[0, blockDim.x)，threadIdx.y的范围为[0, blockDim.y)，threadIdx.z的范围为[0, blockDim.z)。线程块内线程的索引与线程ID对应关系如下：</p><ul><li><p>对于一维线程块，其线程ID为blockIdx.x * blockDim.x + threadIdx.x。</p><p><img src="`+d+`" alt></p></li><li><p>对于二维线程块，其线程ID为二维结构，其计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">thread_id_x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="n">thread_id_y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">y</span><span class="p">;</span>
</code></pre></div></li><li><p>对于三维线程块，其线程ID为三维结构，其计算公式为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">thread_id_x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="n">thread_id_y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">y</span><span class="p">;</span>
<span class="n">thread_id_z</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">z</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">z</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">z</span><span class="p">;</span>
</code></pre></div></li></ul></li></ul><p>当前提供了以下仅在Device上可用的int类型的内置变量：</p><ul><li><p>warpSize</p><p>const int32_t类型变量，表示一个线程束（Warp）中的线程数量，当前为固定值32。</p></li></ul><h2 id="编译器内置数据类型">编译器内置数据类型<span id="section1835494915576"></span><a class="header-anchor" href="#编译器内置数据类型">​</a></h2><p>目前提供了一系列适用于Device侧的数据类型，包括标量和短向量。短向量是由多个元素组成的简单向量。以下数据类型是编译器默认支持的数据类型，使用时无需引入头文件。</p><p><strong>表2</strong> 标量数据类型</p><p><span id="table114921244133211"></span></p><table><thead><tr><th>类型</th><th>数据类型</th><th>描述</th><th>Size（bit）</th><th>取值范围</th></tr></thead><tbody><tr><td>布尔型</td><td>bool</td><td>全0代表false，否则代表true。</td><td>8</td><td>true, false</td></tr><tr><td>整型</td><td>uint8_t</td><td>unsigned char</td><td>8</td><td>[0, 255]</td></tr><tr><td>整型</td><td>int8_t</td><td>signed char</td><td>8</td><td>[-128, 127]</td></tr><tr><td>整型</td><td>uint16_t</td><td>unsigned short</td><td>16</td><td>[0, 65535]</td></tr><tr><td>整型</td><td>int16_t</td><td>signed short</td><td>16</td><td>[-32768, 32767]</td></tr><tr><td>整型</td><td>uint32_t</td><td>unsigned int</td><td>32</td><td>[0, 4294967295]</td></tr><tr><td>整型</td><td>int32_t</td><td>signed int</td><td>32</td><td>[-2147483648, 2147483647]</td></tr><tr><td>整型</td><td>uint64_t</td><td>unsigned long</td><td>64</td><td>[0,18446744073709551615]</td></tr><tr><td>整型</td><td>int64_t</td><td>signed long</td><td>64</td><td>[-9223372036854775808, 9223372036854775807]</td></tr><tr><td>浮点型</td><td>float8_e4m3_t</td><td>符号位宽1，指数位宽4，尾数位宽3</td><td>8</td><td>[2<sup>6</sup> - 2<sup>9</sup>, 2<sup>9</sup> - 2<sup>6</sup>]</td></tr><tr><td>浮点型</td><td>float8_e5m2_t</td><td>符号位宽1，指数位宽5，尾数位宽2</td><td>8</td><td>[2<sup>13</sup> - 2<sup>16</sup>, 2<sup>16</sup> - 2<sup>13</sup>]</td></tr><tr><td>浮点型</td><td>hifloat8_t</td><td>符号位宽1，点域位宽2，指数与尾数位宽由点域编码决定</td><td>8</td><td>点域编码决定数据精度与取值范围</td></tr><tr><td>浮点型</td><td>half</td><td>符号位宽1，指数位宽5，尾数位宽10</td><td>16</td><td>[2<sup>5</sup> - 2<sup>16</sup>, 2<sup>16</sup> - 2<sup>5</sup>]</td></tr><tr><td>浮点型</td><td>bfloat16_t</td><td>符号位宽1，指数位宽8，尾数位宽7</td><td>16</td><td>[2<sup>120</sup> - 2<sup>128</sup>, 2<sup>128</sup> - 2<sup>120</sup>]</td></tr><tr><td>浮点型</td><td>float</td><td>符号位宽1，指数位宽8，尾数位宽23</td><td>32</td><td>[2<sup>104</sup> - 2<sup>128</sup>, 2<sup>128</sup> - 2<sup>104</sup>]</td></tr></tbody></table><p>短向量数据类型分为Vector X2、Vector X3、Vector X4，表示一个短向量变量有2、3、4个元素，当前支持的类型分布如下：</p><p><span id="table49986503175"></span></p><table><thead><tr><th>元素数据类型</th><th>Vector X2</th><th>Vector X3</th><th>Vector X4</th></tr></thead><tbody><tr><td>unsigned char</td><td>uchar2</td><td>uchar3</td><td>uchar4</td></tr><tr><td>signed char</td><td>char2</td><td>char3</td><td>char4</td></tr><tr><td>unsigned short (16bit)</td><td>ushort2</td><td>ushort3</td><td>ushort4</td></tr><tr><td>signed short (16bit)</td><td>short2</td><td>short3</td><td>short4</td></tr><tr><td>unsigned int</td><td>uint2</td><td>uint3</td><td>uint4</td></tr><tr><td>signed int</td><td>int2</td><td>int3</td><td>int4</td></tr><tr><td>无符号的长整型(64bit)</td><td>ulonglong2</td><td>ulonglong3</td><td>ulonglong4</td></tr><tr><td>有符号的长整型(64bit)</td><td>longlong2</td><td>longlong3</td><td>longlong4</td></tr><tr><td>无符号的长整型(64bit)</td><td>ulong2</td><td>ulong3</td><td>ulong4</td></tr><tr><td>有符号的长整型(64bit)</td><td>long2</td><td>long3</td><td>long4</td></tr><tr><td>浮点型，1符号位，2指数位，1尾数位</td><td>float4_e2m1x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，1指数位，2尾数位</td><td>float4_e1m2x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，4指数位，3尾数位</td><td>float8_e4m3x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，5指数位，2尾数位</td><td>float8_e5m2x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型hif8</td><td>hifloat8x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，5指数位，10尾数位</td><td>half2</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，8指数位，7尾数位</td><td>bfloat16x2_t</td><td>-</td><td>-</td></tr><tr><td>浮点型，1符号位，8指数位，23尾数位</td><td>float2</td><td>float3</td><td>float4</td></tr></tbody></table><p><strong>表3</strong> 短向量数据类型</p><p><span id="table13856144241"></span></p><table><thead><tr><th>数据类型</th><th>内存大小（字节）</th><th>地址对齐（字节）</th></tr></thead><tbody><tr><td>char2、 uchar2</td><td>2</td><td>2</td></tr><tr><td>char3、 uchar3、 char4、 uchar4</td><td>4</td><td>4</td></tr><tr><td>short2、 ushort2</td><td>4</td><td>4</td></tr><tr><td>short3、 ushort3、 short4、 ushort4</td><td>8</td><td>8</td></tr><tr><td>int2、 uint2</td><td>8</td><td>8</td></tr><tr><td>int3、 uint3、 int4、 uint4</td><td>16</td><td>16</td></tr><tr><td>long2、 ulong2</td><td>16</td><td>16</td></tr><tr><td>long3、 ulong3、 long4、 ulong4</td><td>32</td><td>32</td></tr><tr><td>longlong2、 ulonglong2</td><td>16</td><td>16</td></tr><tr><td>longlong3、 ulonglong3、 longlong4、 ulonglong4</td><td>32</td><td>32</td></tr><tr><td>float2</td><td>8</td><td>8</td></tr><tr><td>float3、 float4</td><td>16</td><td>16</td></tr><tr><td>float4_e2m1x2_t、 float4_e1m2x2_t</td><td>1</td><td>1</td></tr><tr><td>float8_e4m3x2_t、 float8_e5m2x2_t、 hifloat8x2_t</td><td>2</td><td>2</td></tr><tr><td>half2、bfloat16x2_t</td><td>4</td><td>4</td></tr></tbody></table><h2 id="运算符">运算符<span id="section186787252339"></span><a class="header-anchor" href="#运算符">​</a></h2><p>SIMT编程提供了一系列运算符，用于执行数学运算。以下是支持的运算符列表。</p><p><strong>表4</strong> SIMT编程支持的运算符列表</p><p><span id="table11745172843710"></span></p><table><thead><tr><th>类别</th><th>运算符</th><th>bool</th><th>int8_t/uint8_t/int16_t/uint16_t/int32_t/uint32_t/int64_t/uint64_t</th><th>half/bfloat16_t/float</th><th>half2/bfloat16x2_t</th><th>hifloat8_t</th></tr></thead><tbody><tr><td>算术运算符</td><td>+</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>-</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>*</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>/</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>%</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>算术运算符</td><td>++</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>--</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>算术运算符</td><td>- (取反)</td><td>x</td><td>√</td><td>√</td><td>√</td><td>x</td></tr><tr><td>比较运算符</td><td>&lt;</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>比较运算符</td><td>&lt;=</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>比较运算符</td><td>&gt;</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>比较运算符</td><td>&gt;=</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>比较运算符</td><td>==</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>比较运算符</td><td>!=</td><td>x</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>&amp;</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>|</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>^</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>~</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>&lt;&lt;</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>位运算符</td><td>&gt;&gt;</td><td>x</td><td>√</td><td>x</td><td>x</td><td>x</td></tr><tr><td>逻辑运算符</td><td>&amp;&amp;</td><td>√</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>逻辑运算符</td><td>||</td><td>√</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>逻辑运算符</td><td>!</td><td>√</td><td>√</td><td>√</td><td>x</td><td>x</td></tr><tr><td>条件运算符</td><td>a ? b : c</td><td>√</td><td>√</td><td>√</td><td>√</td><td>x</td></tr></tbody></table><blockquote><p><strong>约束说明</strong>：除法运算符（/）当前不支持Subnormal（指数位全为0，且尾数位不全为0，表示接近零的极小值）输入，当输入为Subnormal值时会被刷为0。</p></blockquote><p>运算符使用示例如下所示：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 加法运算</span>
<span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span><span class="w"> </span>

<span class="c1">// 取反运算</span>
<span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="o">-</span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]);</span>

<span class="c1">// 比较运算</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">])</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="p">}</span>

<span class="c1">// 按位与运算</span>
<span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>

<span class="c1">// 逻辑或运算</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">||</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">])</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="p">}</span>

<span class="c1">// 条件运算</span>
<span class="n">res</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">x</span><span class="p">[</span><span class="n">idx</span><span class="p">]</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">y</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
</code></pre></div><h2 id="核函数（Kernel）配置">核函数（Kernel）配置<span id="核函数配置"></span><span id="section97005415463"></span><a class="header-anchor" href="#核函数（Kernel）配置">​</a></h2><p>在调用__global__限定符修饰的函数时必须指定执行配置。执行配置通过在函数名和带括号的参数列表之间插入如下形式的表达式来指定：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span>
</code></pre></div><p>其中：</p><ul><li>blocks_per_grid：dim3类型，用于指定网格（Grid）的维度与规模。blocks_per_grid.x * blocks_per_grid.y * blocks_per_grid.z等于启动的线程块总数，不能超过65535。</li><li>threads_per_block：dim3类型，用于指定每个线程块（Thread Block）的维度与规模。threads_per_block.x * threads_per_block.y * threads_per_block.z等于每个线程块包含的线程数，需要小于等于__launch_bounds__配置。</li><li>dyn_ubuf_size：size_t类型，用于指定每个线程块动态分配的共享内存大小，单位为字节。这部分内存供数组使用，具体用法请参考<a href="../programming_model/ai_core_simt_programming/memory_hierarchy.html#%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98">共享内存</a>中的“动态申请”方式。</li><li>stream：aclrtStream类型，指定关联的流，用于维护异步操作的执行顺序。</li></ul><p>以下示例展示了核函数（Kernel）的声明与调用方式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 声明</span>
<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">total_length</span><span class="p">);</span>
<span class="c1">// 调用</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">blocks_per_grid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span><span class="w"> </span><span class="c1">// Number of thread blocks (Grid size)</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">threads_per_block</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span><span class="w"> </span><span class="c1">// Number of threads per block (Block size)</span>
<span class="kt">size_t</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="p">;</span><span class="w"> </span><span class="c1">// need 1024 Byte dynamic memory</span>
<span class="n">add_custom</span><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="mi">1024</span><span class="p">);</span><span class="w"> </span><span class="c1">//blocks_per_grid和threads_per_block会被隐式转换为dim3类型</span>
</code></pre></div><p>在执行函数之前，会先对上述配置参数进行校验。如果blocks_per_grid或threads_per_block超出设备的最大允许规模，或dyn_ubuf_size超过分配静态内存后剩余的可用共享内存，该函数将会执行失败。</p><p>一个核函数（Kernel）所使用的寄存器数量决定了单个线程块内可启动的线程数上限。核函数（Kernel）使用的寄存器数量通过 __launch_bounds__()限定符或 __maxnreg__()限定符指定。</p><p>使用上述两个可选配置的限定符时，请注意如下约束：</p><ul><li>__launch_bounds__或__maxnreg__只能在__global__函数中使用。</li><li>同一函数不能同时配置__launch_bounds__和__maxnreg__。</li></ul><p>在多线程并发执行时，每个线程使用较少的寄存器可以让单个线程块内启动更多的线程。因此，编译器会采用启发式算法，将寄存器溢出（register spilling）和指令数量控制在最低水平，同时尽量减少寄存器的使用量。应用程序可以通过在__global__函数定义中使用__launch_bounds__()限定符来限制启动边界（launch bounds），提供附加信息辅助编译器优化这一过程，这属于可选配置。</p><ul><li><p>__launch_bounds__(N) <span id="li23861114618"></span></p><p>函数标记宏，在核函数（Kernel）上可选配置，用于指定核函数（Kernel）启动的最大线程数。最大线程数决定了每个线程可分配的寄存器数量，具体对应关系请见下表，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现寄存器溢出等问题。建议最大线程数与启动核函数（Kernel）时的dim3线程数保持一致。</p><p><strong>表5</strong> __launch_bounds__(N)与每个线程可用的寄存器个数的关系</p><p><span id="table1715318510594"></span></p><table><thead><tr><th>N</th><th>每个线程可用寄存器个数</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table><p>配置SIMT函数最大线程数为512，每个Thread可用寄存器数为64，示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__launch_bounds__</span><span class="p">(</span><span class="mi">512</span><span class="p">)</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
</code></pre></div><p>__launch_bounds__(N)的参数N需要满足：</p><ul><li>N &gt;= dimx * dimy * dimz；dimx, dimy, dimz为表示线程的dim3结构体。</li><li>N的取值范围为1到2048。</li><li>若未配置__launch_bounds__，最大线程数默认为1024。</li></ul></li></ul><p>为了支持底层性能调优，应用程序可以通过在__global__函数定义中使用 __maxnreg__()限定符，用于向编译器传递性能调优意图。该限定符直接限制单个线程在一个线程块内最多可分配的寄存器数量。</p><ul><li><p>__maxnreg__(N) <span id="section_maxnreg"></span></p><p>函数标记宏，在核函数（Kernel）上可选配置，用于在编译期指定单个线程在一个线程块内最多可分配的寄存器数量。</p><p>__maxnreg__(N)的参数N需要满足：</p><ul><li>N的取值范围为(0, 128]区间的整数;</li><li>若输入值N的范围为(0, 16]，则每个线程最多可以使用16个寄存器；若输入值N的范围为(16, 32]，则每个线程最多可以使用32个寄存器；若输入值N的范围为(32, 64]，则每个线程最多可以使用64个寄存器；若输入值N的范围为(64, 128]，则每个线程最多可以使用127个寄存器；</li><li>若未配置__maxnreg__，单个线程最多可分配的寄存器数量默认为32。</li></ul><p>每个线程可用的最大寄存器数量对每个block实际启动的线程数有限制，具体对应关系请见下表。</p><p><strong>表6</strong> __maxnreg__的每个Thread最多可分配的寄存器数与每个block实际可启动的线程数</p><table><thead><tr><th>单个线程最多可分配的寄存器数量(个)</th><th>每个block实际可启动的线程数(个)</th></tr></thead><tbody><tr><td>16</td><td>1~2048</td></tr><tr><td>32</td><td>1~1024</td></tr><tr><td>64</td><td>1~512</td></tr><tr><td>127</td><td>1~256</td></tr></tbody></table><p>配置SIMT函数单个线程最多可分配的寄存器数量为64，示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__maxnreg__</span><span class="p">(</span><span class="mi">64</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
</code></pre></div></li></ul></article></div>`,1)])])}const g=a(l,[["render",c]]);export{u as __pageData,g as default};
